// ============================================================
// MAIN PAGE
// ============================================================

export default function CarouselPage() {
  const [lang, setLang] = useState<Lang>("ru");
  const t = T[lang];
  const [fontId, setFontId] = useState<FontId>(DEFAULT_FONT);
  const [surfaceId, setSurfaceId] = useState<SurfaceId>(DEFAULT_SURFACE);
  const [accentId, setAccentId] = useState<AccentId>(DEFAULT_ACCENT);
  const [purposeId, setPurposeId] = useState<PurposeId>(DEFAULT_PURPOSE);
  const [formatId, setFormatId] = useState<FormatId>(DEFAULT_FORMAT);
  const [bgType, setBgType] = useState<BgType>(DEFAULT_BG);
  const [lookId, setLookId] = useState<LookId>(DEFAULT_LOOK);
  const [motionId, setMotionId] = useState<MotionId>("editorial");
  const [durationSec, setDurationSec] = useState(2.5);
  const [exporting, setExporting] = useState(false);
  const [exportStatus, setExportStatus] = useState("");
  const langRef = useRef<Lang>("ru");
  langRef.current = lang;
  const offscreenRefs = useRef<(HTMLDivElement | null)[]>([]);

  const canvasW = FORMAT_PRESETS[formatId].w;
  const canvasH = FORMAT_PRESETS[formatId].h;
  const preset = composePreset(FONT_STYLES[fontId], SURFACES[surfaceId], ACCENTS[accentId], purposeId, lookId);
  // A look pins the background type; with no look active the manual choice wins.
  const effectiveBg = lookBgType(lookId) ?? bgType;
  // Same pattern for motion — Maximalist/Caption pin "stamp" since their
  // filled panels need to arrive as one object, not fade in place.
  const effectiveMotion = lookMotionId(lookId) ?? motionId;

  const captureSlide = useCallback(
    async (index: number): Promise<string | null> => {
      const el = offscreenRefs.current[index];
      if (!el) return null;

      el.style.opacity = "1";
      el.style.zIndex = "-1";
      // requestAnimationFrame never fires while the page is hidden (a
      // backgrounded tab, or a preview pane that is not on screen), which
      // stalls the whole export instead of failing. Fall back to a timer so a
      // capture can complete without the compositor.
      await (document.hidden
        ? new Promise<void>((r) => setTimeout(() => r(), 32))
        : new Promise<void>((r) => requestAnimationFrame(() => r())));

      const opts = {
        width: canvasW,
        height: canvasH,
        pixelRatio: 2,
        cacheBust: true,
        backgroundColor: preset.bg,
      };

      // Double-call: first warms fonts/images, second captures
      await toPng(el, opts);
      await new Promise((r) => setTimeout(r, 120));
      const dataUrl = await toPng(el, opts);

      el.style.opacity = "0";
      el.style.zIndex = "-1";
      return dataUrl;
    },
    [preset.bg, canvasW, canvasH]
  );

  // Lets a host page (agentco's studio) capture slides and read the chosen
  // design without forking this component further. Nothing reads it when
  // the builder runs on its own.
  useEffect(() => {
    (window as unknown as { __carouselStudio?: unknown }).__carouselStudio = {
      slideCount: SLIDES.length,
      slideTypes: SLIDES.map((s) => s.type),
      capture: captureSlide,
      settings: { lookId, fontId, surfaceId, accentId, purposeId, formatId, bgType: effectiveBg },
    };
  }, [captureSlide, lookId, fontId, surfaceId, accentId, purposeId, formatId, effectiveBg]);

  const exportSlide = useCallback(
    async (index: number) => {
      const dataUrl = await captureSlide(index);
      if (!dataUrl) return;
      const link = document.createElement("a");
      link.download = `${String(index + 1).padStart(2, "0")}-${SLIDES[index].type}.png`;
      link.href = dataUrl;
      link.click();
    },
    [captureSlide]
  );

  const exportAll = useCallback(async () => {
    setExporting(true);
    const tl = T[langRef.current];
    for (let i = 0; i < SLIDES.length; i++) {
      setExportStatus(tl.statusExport(i + 1, SLIDES.length));
      await exportSlide(i);
      await new Promise((r) => setTimeout(r, 300));
    }
    setExportStatus(tl.statusDone);
    setExporting(false);
    setTimeout(() => setExportStatus(""), 2000);
  }, [exportSlide]);

  // ---- Animated export ----
  //
  // Frames are rendered by setting a progress value on the offscreen node and
  // capturing it, then encoded to MP4 by ffmpeg on the server. Capture runs at
  // pixelRatio 1 because the canvas presets are already at native output size.
  const exportAnimated = useCallback(async () => {
    const tl = T[langRef.current];
    const fps = 30;
    const preflight = await fetch("/api/encode").then((r) => r.json()).catch(() => null);
    if (!preflight || !preflight.ok) {
      const problems = preflight?.problems?.join("; ") ?? "server unreachable";
      setExportStatus(`Cannot start: ${problems}`);
      return;
    }

    const sessionId = `s-${Math.random().toString(36).slice(2, 10)}-${SLIDES.length}`;
    const motion = MOTION_PRESETS[effectiveMotion];
    const total = frameCount(durationSec, fps);

    setExporting(true);
    try {
      for (let i = 0; i < SLIDES.length; i++) {
        const el = offscreenRefs.current[i];
        if (!el) continue;

        el.style.opacity = "1";
        el.style.zIndex = "-1";

        const opts = {
          width: canvasW,
          height: canvasH,
          pixelRatio: 1,
          cacheBust: true,
          backgroundColor: preset.bg,
        };

        // Warm fonts and images once per slide, not once per frame.
        applyFrame(el, 1, motion);
        await nextFrame();
        await toPng(el, opts);

        for (let f = 0; f < total; f++) {
          applyFrame(el, f / (total - 1), motion);
          await nextFrame();
          const dataUrl = await toPng(el, opts);

          let posted = false;
          for (let attempt = 0; attempt < 2 && !posted; attempt++) {
            const res = await fetch("/api/frames", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ sessionId, slideIndex: i, frameIndex: f, dataUrl }),
            }).catch(() => null);
            posted = !!res && res.ok;
          }
          if (!posted) throw new Error(`frame ${f + 1} of slide ${i + 1} could not be saved`);

          setExportStatus(`${tl.statusExport(i + 1, SLIDES.length)} — ${f + 1}/${total}`);
        }

        resetFrame(el);
        el.style.opacity = "0";

        setExportStatus(`${tl.statusExport(i + 1, SLIDES.length)} — encoding`);
        const enc = await fetch("/api/encode", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sessionId, slideIndex: i, name: SLIDES[i].type, fps }),
        }).then((r) => r.json());

        if (!enc.ok) throw new Error(enc.error ?? "encode failed");
      }
      setExportStatus(`Done — MP4s in ${preflight.exportDir}`);
    } catch (err) {
      setExportStatus(err instanceof Error ? err.message : String(err));
    } finally {
      offscreenRefs.current.forEach((el) => {
        if (el) {
          resetFrame(el);
          el.style.opacity = "0";
        }
      });
      setExporting(false);
    }
  }, [effectiveMotion, durationSec, canvasW, canvasH, preset.bg]);

  const exportPdf = useCallback(async () => {
    setExporting(true);
    const isLandscape = canvasW > canvasH;
    const orientation = isLandscape ? "landscape" : "portrait";
    const { default: jsPDF } = await import("jspdf");
    const pdf = new jsPDF({ orientation, unit: "px", format: [canvasW, canvasH], hotfixes: ["px_scaling"] });
    const jpegOpts = { width: canvasW, height: canvasH, pixelRatio: 2, cacheBust: true, backgroundColor: preset.bg, quality: 0.92 };

    const tl = T[langRef.current];
    for (let i = 0; i < SLIDES.length; i++) {
      setExportStatus(tl.statusPdf(i + 1, SLIDES.length));
      const el = offscreenRefs.current[i];
      if (!el) continue;

      el.style.opacity = "1";
      el.style.zIndex = "-1";
      await new Promise<void>((r) => requestAnimationFrame(() => r()));
      await toJpeg(el, jpegOpts); // warm up
      await new Promise((r) => setTimeout(r, 120));
      const dataUrl = await toJpeg(el, jpegOpts);
      el.style.opacity = "0";
      el.style.zIndex = "-1";

      if (i > 0) pdf.addPage([canvasW, canvasH], orientation);
      pdf.addImage(dataUrl, "JPEG", 0, 0, canvasW, canvasH);
      await new Promise((r) => setTimeout(r, 200));
    }

    pdf.save("slides.pdf");
    setExportStatus(T[langRef.current].statusDone);
    setExporting(false);
    setTimeout(() => setExportStatus(""), 2000);
  }, [preset.bg, canvasW, canvasH]);

  return (
    <CanvasSizeContext.Provider value={{ w: canvasW, h: canvasH }}>
    <div suppressHydrationWarning style={{ minHeight: "100vh", padding: 32 }}>
      {/* Toolbar */}
      <div style={{ marginBottom: 32 }}>
        {/* Title + Export + Lang toggle */}
        <div style={{ display: "flex", alignItems: "flex-start", gap: 16, marginBottom: 20 }}>
          <div>
            <h1 style={{ fontSize: 20, fontWeight: 700, margin: 0, textWrap: "balance" } as React.CSSProperties}>{t.appTitle}</h1>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>
              {FORMAT_PRESETS[formatId].name} — {canvasW}×{canvasH}
            </div>
          </div>
          <div style={{ marginLeft: "auto", display: "flex", gap: 8, alignItems: "center" }}>
            {/* Lang toggle */}
            <div style={{ display: "flex", borderRadius: 8, overflow: "hidden", border: "1px solid #333" }}>
              {(["en", "ru"] as Lang[]).map((l) => (
                <button
                  key={l}
                  onClick={() => setLang(l)}
                  className="tb-btn"
                  style={{
                    padding: "9px 12px",
                    minHeight: 36,
                    border: "none",
                    background: lang === l ? "#555" : "transparent",
                    color: lang === l ? "#fff" : "#888",
                    cursor: "pointer",
                    fontSize: 11,
                    fontWeight: 600,
                    textTransform: "uppercase",
                  }}
                >
                  {l}
                </button>
              ))}
            </div>
            <button onClick={exportPdf} disabled={exporting} style={{ padding: "8px 20px", minWidth: 120, minHeight: 36, borderRadius: 8, border: "none", background: exporting ? "#444" : "#6366F1", color: "#fff", cursor: exporting ? "not-allowed" : "pointer", fontSize: 14, fontWeight: 600, fontVariantNumeric: "tabular-nums" }} className="tb-btn">
              {exporting ? exportStatus : t.btnPdf}
            </button>
            {/* Hidden where ffmpeg is unavailable (agentco's studio sets this). */}
            {"1" !== "1" && (
              <button onClick={exportAnimated} disabled={exporting} style={{ padding: "8px 20px", minWidth: 120, minHeight: 36, borderRadius: 8, border: "none", background: exporting ? "#444" : "#EC4899", color: "#fff", cursor: exporting ? "not-allowed" : "pointer", fontSize: 14, fontWeight: 600, fontVariantNumeric: "tabular-nums" }} className="tb-btn">
                {exporting ? exportStatus : t.btnVideo}
              </button>
            )}
            <button onClick={exportAll} disabled={exporting} style={{ padding: "8px 20px", minWidth: 110, minHeight: 36, borderRadius: 8, border: "none", background: exporting ? "#444" : "#22C55E", color: "#fff", cursor: exporting ? "not-allowed" : "pointer", fontSize: 14, fontWeight: 600, fontVariantNumeric: "tabular-nums" }} className="tb-btn">
              {exporting ? exportStatus : t.btnAll}
            </button>
          </div>
        </div>

        {/* 5-row axis toolbar — order: Format → Mode → Font → Color → Background */}
        {/* key={lang} causes remount → tbFadeIn animation plays on language switch */}
        <div key={lang} className="tb-lang-fade" style={{ display: "flex", flexDirection: "column", gap: 8 }}>

          {/* Look — curated preset; pins the axes below it */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowLook}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.values(LOOKS).map((lk) => (
                <button
                  key={lk.id}
                  onClick={() => {
                    setLookId(lk.id);
                    // Apply the look's font pin so the axis row reflects reality.
                    if (lk.pins.font) setFontId(lk.pins.font);
                    if (lk.pins.surface) setSurfaceId(lk.pins.surface);
                  }}
                  style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: lookId === lk.id ? "2px solid #EC4899" : "1px solid #333", background: lookId === lk.id ? "#EC4899" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }}
                  className="tb-btn"
                >
                  {lk.name}
                </button>
              ))}
            </div>
          </div>

          {/* Motion — animated export only; static exports ignore it */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowMotion}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.values(MOTION_PRESETS).map((mp) => (
                <button key={mp.id} onClick={() => setMotionId(mp.id)} style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: effectiveMotion === mp.id ? "2px solid #EC4899" : "1px solid #333", background: effectiveMotion === mp.id ? "#EC4899" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {mp.name}
                </button>
              ))}
              <span style={{ width: 12 }} />
              {[2, 2.5, 3].map((d) => (
                <button key={d} onClick={() => setDurationSec(d)} style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: durationSec === d ? "2px solid #EC4899" : "1px solid #333", background: durationSec === d ? "#EC4899" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {d}s
                </button>
              ))}
            </div>
          </div>

          {/* Format */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowFormat}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.values(FORMAT_PRESETS).map((f) => (
                <button key={f.id} onClick={() => setFormatId(f.id)} title={f.platform} style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: formatId === f.id ? "2px solid #06B6D4" : "1px solid #333", background: formatId === f.id ? "#06B6D4" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {f.name}
                </button>
              ))}
            </div>
          </div>

          {/* Mode */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowMode}</span>
            <div style={{ display: "flex", gap: 6 }}>
              {(["carousel", "presentation"] as PurposeId[]).map((p) => (
                <button key={p} onClick={() => setPurposeId(p)} style={{ padding: "9px 14px", minWidth: 110, minHeight: 36, borderRadius: 8, border: purposeId === p ? "2px solid #F59E0B" : "1px solid #333", background: purposeId === p ? "#F59E0B" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {t.modes[p]}
                </button>
              ))}
            </div>
          </div>

          {/* Font */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowFont}</span>
            <div style={{ display: "flex", gap: 6 }}>
              {Object.values(FONT_STYLES).map((f) => (
                <button key={f.id} onClick={() => setFontId(f.id)} style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: fontId === f.id ? "2px solid #6366F1" : "1px solid #333", background: fontId === f.id ? "#6366F1" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {f.name}
                </button>
              ))}
            </div>
          </div>

          {/* Surface (bg + text) */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowSurface}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.values(SURFACES).map((s) => (
                <button key={s.id} onClick={() => setSurfaceId(s.id)} style={{ padding: "9px 14px", minHeight: 36, borderRadius: 8, border: surfaceId === s.id ? "2px solid #6366F1" : "1px solid #333", background: surfaceId === s.id ? "#6366F1" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {t.surfaces[s.id]}
                </button>
              ))}
            </div>
          </div>

          {/* Accent (pop color) */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowAccent}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {Object.values(ACCENTS).map((a) => (
                <button
                  key={a.id}
                  onClick={() => setAccentId(a.id)}
                  title={t.accents[a.id]}
                  style={{
                    padding: "9px 14px",
                    minHeight: 36,
                    borderRadius: 8,
                    border: accentId === a.id ? `2px solid ${a.color}` : "1px solid #333",
                    background: accentId === a.id ? a.color : "transparent",
                    color: accentId === a.id ? "#000" : "#fff",
                    cursor: "pointer",
                    fontSize: 12,
                    fontWeight: 600,
                  }}
                  className="tb-btn"
                >
                  {t.accents[a.id]}
                </button>
              ))}
            </div>
          </div>

          {/* Background */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: "#666", width: 90, flexShrink: 0 }}>{t.rowBg}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {(["none", "blobs", "grid", "lines", "paper", "noise", "bignumber", "glow", "bloom", "aurora", "stealthbloom", "sunglow", "organicbloom", "swissrule"] as BgType[]).map((bg) => (
                <button key={bg} onClick={() => setBgType(bg)} style={{ padding: "9px 12px", minHeight: 36, borderRadius: 8, border: bgType === bg ? "2px solid #22C55E" : "1px solid #333", background: bgType === bg ? "#22C55E" : "transparent", color: "#fff", cursor: "pointer", fontSize: 12, fontWeight: 500 }} className="tb-btn">
                  {t.bgs[bg]}
                </button>
              ))}
            </div>
          </div>

        </div>
      </div>

      {/* Preview Grid */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
          gap: 20,
        }}
      >
        {SLIDES.map((slide, i) => (
          <div key={i}>
            <div
              onClick={() => !exporting && exportSlide(i)}
              className="slide-card"
              title="Click to export this slide"
            >
              <SlidePreview
                data={slide}
                preset={preset}
                index={i}
                total={SLIDES.length}
                bgType={effectiveBg}
              />
            </div>
            <div
              style={{
                fontSize: 12,
                color: "#888",
                marginTop: 8,
                textAlign: "center",
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {i + 1}/{SLIDES.length} — {slide.type}
            </div>
          </div>
        ))}
      </div>

      {/* Offscreen slides for export — always rendered at (0,0), invisible via opacity */}
      {SLIDES.map((slide, i) => (
        <div
          key={`export-${i}`}
          ref={(el) => {
            offscreenRefs.current[i] = el;
          }}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: canvasW,
            height: canvasH,
            opacity: 0,
            pointerEvents: "none",
            zIndex: -1,
            fontFamily: preset.fontFamily,
          }}
        >
          <Slide data={slide} preset={preset} index={i} total={SLIDES.length} bgType={effectiveBg} />
        </div>
      ))}

      {/* Info */}
      <div
        style={{
          marginTop: 32,
          fontSize: 13,
          color: "#666",
          textAlign: "center",
        }}
      >
        {t.footer(canvasW, canvasH, SLIDES.length)}
      </div>
    </div>
    </CanvasSizeContext.Provider>
  );
}
